edge for the "7" key:
  source "key7", target "display", triggerEvent "click", actionType "setState"
  handler:
    const d = get('fresh') === '1' ? '' : String(get('display') ?? '');
    set('display', (d === '0' ? '' : d) + '7');
    set('fresh', '0');

edge for the "+" key:
  source "keyPlus", target "display", triggerEvent "click", actionType "setState"
  handler:
    set('acc', String(num(get('display'))));
    set('op', '+');
    set('fresh', '1');

edge for the "=" key:
  source "keyEquals", target "display", triggerEvent "click", actionType "custom"
  handler:
    const a = num(get('acc'));
    const b = num(get('display'));
    const op = String(get('op') ?? '');
    let r = b;
    if (op === '+') r = a + b;
    else if (op === '-') r = a - b;
    else if (op === '*') r = a * b;
    else if (op === '/') r = b === 0 ? 0 : a / b;
    set('display', String(Math.round(r * 1e10) / 1e10));
    set('op', '');
    set('fresh', '1');

edge for the "C" key:
  source "keyClear", target "display", triggerEvent "click", actionType "setState"
  handler:
    set('display', '0'); set('acc', '0'); set('op', ''); set('fresh', '1');

