1:/** Cloudflare Worker entry point for the vinext-starter template. */
2:import { handleImageOptimization, DEFAULT_DEVICE_SIZES, DEFAULT_IMAGE_SIZES } from "vinext/server/image-optimization";
3:import handler from "vinext/server/app-router-entry";
4:
5:interface Env {
6:  ASSETS: Fetcher;
7:  DB: D1Database;
8:  IMAGES: {
9:    input(stream: ReadableStream): {
10:      transform(options: Record<string, unknown>): {
11:        output(options: { format: string; quality: number }): Promise<{ response(): Response }>;
12:      };
13:    };
14:  };
15:}
16:
17:interface ExecutionContext {
18:  waitUntil(promise: Promise<unknown>): void;
19:  passThroughOnException(): void;
20:}
21:
22:// Image security config. SVG sources with .svg extension auto-skip the
23:// optimization endpoint on the client side (served directly, no proxy).
24:// To route SVGs through the optimizer (with security headers), set
25:// dangerouslyAllowSVG: true in next.config.js and uncomment below:
26:// const imageConfig: ImageConfig = { dangerouslyAllowSVG: true };
27:
28:const worker = {
29:  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
30:    const url = new URL(request.url);
31:
32:    if (url.pathname === "/_vinext/image") {
33:      const allowedWidths = [...DEFAULT_DEVICE_SIZES, ...DEFAULT_IMAGE_SIZES];
34:      return handleImageOptimization(request, {
35:        fetchAsset: (path) => env.ASSETS.fetch(new Request(new URL(path, request.url))),
36:        transformImage: async (body, { width, format, quality }) => {
37:          const result = await env.IMAGES.input(body).transform(width > 0 ? { width } : {}).output({ format, quality });
38:          return result.response();
39:        },
40:      }, allowedWidths);
41:    }
42:
43:    return handler.fetch(request, env, ctx);
44:  },
45:};
