/** Cloudflare Worker entry point for the vinext-starter template. */
import { handleImageOptimization, DEFAULT_DEVICE_SIZES, DEFAULT_IMAGE_SIZES } from "vinext/server/image-optimization";
import handler from "vinext/server/app-router-entry";

interface Env {
  ASSETS: Fetcher;
  DB: D1Database;
  IMAGES: {
    input(stream: ReadableStream): {
      transform(options: Record<string, unknown>): {
        output(options: { format: string; quality: number }): Promise<{ response(): Response }>;
      };
    };
  };
}

interface ExecutionContext {
  waitUntil(promise: Promise<unknown>): void;
  passThroughOnException(): void;
}

// Image security config. SVG sources with .svg extension auto-skip the
// optimization endpoint on the client side (served directly, no proxy).
// To route SVGs through the optimizer (with security headers), set
// dangerouslyAllowSVG: true in next.config.js and uncomment below:
// const imageConfig: ImageConfig = { dangerouslyAllowSVG: true };

const worker = {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);

    if (url.pathname === "/_vinext/image") {
      const allowedWidths = [...DEFAULT_DEVICE_SIZES, ...DEFAULT_IMAGE_SIZES];
      return handleImageOptimization(request, {
        fetchAsset: (path) => env.ASSETS.fetch(new Request(new URL(path, request.url))),
        transformImage: async (body, { width, format, quality }) => {
          const result = await env.IMAGES.input(body).transform(width > 0 ? { width } : {}).output({ format, quality });
          return result.response();
        },
      }, allowedWidths);
    }

    return handler.fetch(request, env, ctx);
  },
};

export default worker;

// Intentionally empty by default.
// Add Drizzle tables here when the site actually needs a database.
// See examples/d1/db/schema.ts for an opt-in example.
export {};

import type { AppComponent, BehaviorEdge } from "./app-graph";

/**
 * The client-side execution runtime.
…
 */

export type StateValue = string | number | boolean | null;
export type AppState = Record<string, StateValue>;

export interface HandlerEvent { … }

export interface HandlerContext { … }

export type CompiledHandler = (context: HandlerContext) => void;

export interface HandlerRunResult { … }

const compileCache = new Map<string, CompiledHandler | null>();

/**
 * Identifiers shadowed to `undefined` inside every handler.
…
 */
const SHADOWED = [
…
] as const;

const SHADOW_PRELUDE = `const ${SHADOWED.map((name) => `${name} = undefined`).join(", ")};`;

export function num(value: unknown): number { … }

/**
 * Wraps a handler body in a function whose only free variables are the context
 * members. Returns null when the body does not parse, so a malformed handler
 * disables one behavior instead of breaking the whole canvas.
 */
export function compileHandler(source: string): CompiledHandler | null { … }

export function isHandlerValid(source: string): boolean {
  return compileHandler(source) !== null;
}

/**
 * Runs every edge triggered by one event against a single working copy of
 * state, so a handler observes writes made by handlers earlier in the batch and
 * the UI re-renders exactly once.
 */
export function runHandlers(
  edges: BehaviorEdge[],
  components: AppComponent[],
  currentState: AppState,
  event: HandlerEvent,
): HandlerRunResult { … }

/** Edges that should fire for a given component + event name. */
export function matchingEdges(
  bindings: BehaviorEdge[],
  componentId: string,
  eventName: string,
): BehaviorEdge[] { … }

/** Resolves what a component should display, preferring its state binding. */
export function displayValue(
  component: AppComponent,
  state: AppState,
): string { … }

