155:export function createId(prefix: string): string {
156:  const cryptoApi = globalThis.crypto;
157:
158:  if (typeof cryptoApi?.randomUUID === "function") {
159:    return `${prefix}-${cryptoApi.randomUUID().slice(0, 8)}`;
160:  }
161:
162:  if (typeof cryptoApi?.getRandomValues === "function") {
163:    const values = new Uint32Array(2);
164:    cryptoApi.getRandomValues(values);
165:    return `${prefix}-${Array.from(values, (value) =>
166:      value.toString(36),
167:    ).join("")}`;
168:  }
169:
170:  return `${prefix}-${Date.now().toString(36)}${Math.random()
171:    .toString(36)
172:    .slice(2, 8)}`;
173:}
