175:export function getStrokeBounds(stroke: InkStroke): Bounds {
176:  const xs = stroke.points.map((point) => point.x);
177:  const ys = stroke.points.map((point) => point.y);
178:  const x = Math.min(...xs);
179:  const y = Math.min(...ys);
180:  return {
181:    x,
182:    y,
183:    width: Math.max(1, Math.max(...xs) - x),
184:    height: Math.max(1, Math.max(...ys) - y),
185:  };
186:}
