188:export function guessComponentType(bounds: Bounds): ComponentType {
189:  const ratio = bounds.width / Math.max(bounds.height, 1);
190:
191:  if (bounds.width < 64 && bounds.height < 64) return "Checkbox";
192:  if (ratio > 4.2) return "TextInput";
193:  if (ratio > 2.1 && bounds.height < 96) return "Button";
194:  if (bounds.height > 150 && bounds.height > bounds.width * 0.72) return "List";
195:  if (bounds.width > 230 && bounds.height > 130) return "Card";
196:  return "Button";
197:}
