import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import test from "node:test";

async function render() {
  const workerUrl = new URL("../dist/server/index.js", import.meta.url);
  workerUrl.searchParams.set("test", `${process.pid}-${Date.now()}`);
  const { default: worker } = await import(workerUrl.href);

  return worker.fetch(
    new Request("http://localhost/", {
      headers: { accept: "text/html" },
    }),
    {
      ASSETS: {
        fetch: async () => new Response("Not found", { status: 404 }),
      },
    },
    {
      waitUntil() {},
      passThroughOnException() {},
    },
  );
}

test("server-renders the blank executable-sketch canvas", async () => {
  const response = await render();
  assert.equal(response.status, 200);
  assert.match(response.headers.get("content-type") ?? "", /^text\/html\b/i);

  const html = await response.text();
  assert.match(html, /<title>Magicapp — executable sketch<\/title>/i);
  assert.match(html, /aria-label="Executable sketch canvas"/);
  assert.match(html, />Draw<\/button>/);
  assert.match(html, />Run<\/button>/);
  assert.match(html, />Process<\/span>/);
  assert.match(html, />nothing new<\/small>/);
  // The old three-layer workspace is gone; one canvas, two modes.
  assert.doesNotMatch(html, />Behavior<\/button>|>Preview<\/button>/);
  assert.doesNotMatch(html, /codex-preview|react-loading-skeleton/i);
});

test("keeps processing explicit and the agent bridge local to the Mac", async () => {
  const [client, bridge, viteConfig] = await Promise.all([
    readFile(new URL("../app/SketchCompiler.tsx", import.meta.url), "utf8"),
    readFile(new URL("../server/agent-bridge.mjs", import.meta.url), "utf8"),
    readFile(new URL("../vite.config.ts", import.meta.url), "utf8"),
  ]);

  assert.match(client, /onClick=\{\(\) => void processSketch\(\)\}/);
  assert.match(client, /event\.metaKey \|\| event\.ctrlKey/);
  assert.match(client, /stroke\.processed/);
  assert.match(bridge, /const HOST = "127\.0\.0\.1"/);
  assert.match(bridge, /codex[\s\S]*claude[\s\S]*copilot/);
  assert.match(viteConfig, /host:\s*true/);
  assert.match(viteConfig, /"\/agent-api"/);
});

