import { spawn } from "node:child_process";
import { constants as fsConstants } from "node:fs";
import {
  access,
  mkdtemp,
  readFile,
  rm,
  writeFile,
} from "node:fs/promises";
import { createServer } from "node:http";
import { tmpdir } from "node:os";
import { delimiter, dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { parseAgentJson } from "./agent-response.mjs";

const SERVER_DIR = dirname(fileURLToPath(import.meta.url));
const PROJECT_DIR = dirname(SERVER_DIR);
const SCHEMA_PATH = join(SERVER_DIR, "process-response.schema.json");
const schema = JSON.parse(await readFile(SCHEMA_PATH, "utf8"));
const PORT = Number(process.env.MAGICAPP_AGENT_PORT || 8787);
const HOST = "127.0.0.1";
const MAX_BODY_BYTES = 12 * 1024 * 1024;
const MAX_OUTPUT_BYTES = 4 * 1024 * 1024;
// A dense sketch is a genuinely large structured-output job — a 17-component
// keypad takes minutes, not seconds. This is the ceiling before we give up and
// fall back to the local matcher.
const TIMEOUT_MS = 300_000;

const defaultModels = {
  codex: "gpt-5.6-sol",
  claude: "fable",
  copilot: "gpt-5.6-sol",
};

let busy = false;

async function findExecutable(name) {
  const pathEntries = (process.env.PATH || "").split(delimiter);
  for (const entry of pathEntries) {
    if (!entry) continue;
    const candidate = join(entry, name);
    try {
      await access(candidate, fsConstants.X_OK);
      return candidate;
    } catch {
      // Keep looking.
    }
  }
  return null;
}

async function engineAvailability() {
  const [codex, claude, copilot] = await Promise.all([
    findExecutable("codex"),
    findExecutable("claude"),
    findExecutable("copilot"),
  ]);
  return {
    paths: { codex, claude, copilot },
    available: {
      codex: Boolean(codex),
      claude: Boolean(claude),
      copilot: Boolean(copilot),
    },
  };
}

function sendJson(response, status, value) {
  const body = JSON.stringify(value);
  response.writeHead(status, {
    "content-type": "application/json; charset=utf-8",
    "content-length": Buffer.byteLength(body),
    "cache-control": "no-store",
  });
  response.end(body);
}

async function readJson(request) {
  const chunks = [];
  let length = 0;
  for await (const chunk of request) {
    length += chunk.length;
    if (length > MAX_BODY_BYTES) {
      throw new Error("The sketch snapshot is too large.");
    }
    chunks.push(chunk);
  }
  return JSON.parse(Buffer.concat(chunks).toString("utf8"));
}

function parseImage(image) {
  const match =
    typeof image === "string"
      ? image.match(/^data:image\/png;base64,([A-Za-z0-9+/=\s]+)$/)
      : null;
  if (!match) throw new Error("Expected a PNG sketch snapshot.");
  return Buffer.from(match[1], "base64");
}

function makePrompt(input, imagePath) {
  const componentVocabulary = [
    "Text",
    "Button",
    "TextInput",
    "Textarea",
    "Checkbox",
    "Select",
    "Image",
    "Card",
    "List",
    "Modal",
    "Tabs",
    "Navbar",
  ];
  const behaviorVocabulary = [
    "setState",
    "filter",
    "sort",
    "validate",
    "open",
    "close",
    "navigate",
    "fetch",
    "create",
    "update",
    "delete",
    "visibility",
    "custom",
  ];
  const graph = JSON.stringify(input.graph ?? {}, null, 2);
  const canvas = input.canvas ?? { width: 1024, height: 768 };
  const strokeCount = Array.isArray(input.strokes) ? input.strokes.length : 0;

  return `You compile a hand-drawn sketch into a working client-side app.

Inspect the attached PNG at ${imagePath}. It shows, on a paper background:
- Thin grey boxes labeled "<id> · <Type> · <label>" — components that ALREADY
  exist in the app graph. Never recreate these.
- Black ink — a new batch of ${strokeCount} strokes the user just drew. This is
  the only thing you are being asked to interpret.

Canvas coordinates are ${canvas.width} by ${canvas.height}.

Current app graph:
${graph}

The new ink may contain new UI shapes, wiring between existing components,
handwritten notes describing logic, or any mix of the three. Work out which and
return the corresponding new components and new behavior edges together.

Return only the structured response required by the supplied schema.

## Components

- Allowed types: ${componentVocabulary.join(", ")}.
- Use the drawn element's pixel bounding box for x, y, width, height.
- Transcribe handwritten labels. A digit or symbol inside a small box is that
  button's label.
- A long low rectangle with prompt-like text is TextInput. A compact labeled
  rectangle is Button. A wide box holding a number or intended to show output is
  Text. Repeated rows are List. A small square beside text is Checkbox.
- stateKey binds a component to one app-state value:
  - a Text that displays a running value gets that value's key (e.g. "display")
  - a TextInput gets the key its typed value should be stored under
  - a Button almost always has stateKey ""
- confidence is 0 to 1.

## Behaviors

Each edge is one handler bound to one component's event.

- source must be an existing or newly returned component id.
- target is the component the behavior visibly affects; use "" when the logic
  only writes app state.
- triggerEvent is normally click, change, or submit.
- actionType must be one of: ${behaviorVocabulary.join(", ")}.
- One handwritten note may justify MANY edges. "digits append to the display"
  over a keypad means one edge per digit button. Emit them all.
- tests are short behavioral assertions, not executable test files.
- If a mark is ambiguous, omit it. Never invent UI or wiring that is not drawn.

## Handler contract — read carefully

handler is a JavaScript statement body executed in the browser. It is REAL code
that runs; it is not a description. These names are in scope and nothing else:

  state          plain object of all current app state
  get(key)       read one state value
  set(key, val)  write one state value
  event          { type, value, componentId } — value is the typed text for
                 inputs, or the button label for clicks
  self           the component that fired
  target         the target component, or null
  num(v)         coerce anything to a finite number (blank/garbage becomes 0)

No imports, no await, no fetch, no DOM, no timers, no console. Do not declare a
function — write the statements directly. Multiple handlers triggered by the
same event run in order against the same state, and the UI re-renders once.

Write every string literal in handler code with SINGLE quotes. A handler is
carried inside a JSON string, and single quotes keep that escaping trivial.

initialState declares the starting values every handler can rely on. Return it
as key/value pairs; values are strings and handlers coerce with num() as needed.

## Worked example — an arithmetic calculator

Given a display box and drawn keys, correct output looks like:

component: { id: "display", type: "Text", stateKey: "display", label: "0", … }
component: { id: "key7", type: "Button", stateKey: "", label: "7", … }

initialState: [ {key:"display",value:"0"}, {key:"acc",value:"0"},
                {key:"op",value:""}, {key:"fresh",value:"1"} ]

edge for the "7" key:
  source "key7", target "display", triggerEvent "click", actionType "setState"
  handler:
    const d = get('fresh') === '1' ? '' : String(get('display') ?? '');
    set('display', (d === '0' ? '' : d) + '7');
    set('fresh', '0');

edge for the "+" key:
  source "keyPlus", target "display", triggerEvent "click", actionType "setState"
  handler:
    set('acc', String(num(get('display'))));
    set('op', '+');
    set('fresh', '1');

edge for the "=" key:
  source "keyEquals", target "display", triggerEvent "click", actionType "custom"
  handler:
    const a = num(get('acc'));
    const b = num(get('display'));
    const op = String(get('op') ?? '');
    let r = b;
    if (op === '+') r = a + b;
    else if (op === '-') r = a - b;
    else if (op === '*') r = a * b;
    else if (op === '/') r = b === 0 ? 0 : a / b;
    set('display', String(Math.round(r * 1e10) / 1e10));
    set('op', '');
    set('fresh', '1');

edge for the "C" key:
  source "keyClear", target "display", triggerEvent "click", actionType "setState"
  handler:
    set('display', '0'); set('acc', '0'); set('op', ''); set('fresh', '1');

Follow that shape for whatever the user actually drew. Write handlers that
genuinely work when clicked, not placeholders.
`;
}

function runProcess(executable, args, { cwd, input }) {
  return new Promise((resolve, reject) => {
    const child = spawn(executable, args, {
      cwd,
      env: {
        ...process.env,
        NO_COLOR: "1",
        FORCE_COLOR: "0",
      },
      stdio: ["pipe", "pipe", "pipe"],
    });
    let stdout = "";
    let stderr = "";
    let outputTooLarge = false;

    const append = (current, chunk) => {
      const next = current + chunk.toString("utf8");
      if (Buffer.byteLength(next) > MAX_OUTPUT_BYTES) {
        outputTooLarge = true;
        child.kill("SIGTERM");
      }
      return next.slice(0, MAX_OUTPUT_BYTES);
    };

    child.stdout.on("data", (chunk) => {
      stdout = append(stdout, chunk);
    });
    child.stderr.on("data", (chunk) => {
      stderr = append(stderr, chunk);
    });
    child.on("error", reject);

    const timeout = setTimeout(() => {
      child.kill("SIGTERM");
      setTimeout(() => child.kill("SIGKILL"), 1_000).unref();
      reject(new Error("The agent took longer than 150 seconds."));
    }, TIMEOUT_MS);

    child.on("close", (code) => {
      clearTimeout(timeout);
      if (outputTooLarge) {
        reject(new Error("The agent response was unexpectedly large."));
      } else if (code === 0) {
        resolve({ stdout, stderr });
      } else {
        const detail = stderr.trim().split("\n").slice(-3).join(" ");
        reject(
          new Error(
            detail || `The agent command exited with status ${code ?? "unknown"}.`,
          ),
        );
      }
    });

    child.stdin.end(input);
  });
}

// Magicapp is a single-user local tool: the bridge is loopback-only and the
// harnesses run on the owner's own Mac. We therefore trust the environment and
// invoke every engine fully unlocked — all tools, no approval prompts, no
// sandbox — rather than negotiating permissions the iPad can't answer.
async function invokeAgent(engine, executable, model, prompt, imagePath, workDir) {
  const outputPath = join(workDir, "response.json");

  if (engine === "codex") {
    const result = await runProcess(
      executable,
      [
        "exec",
        "--ephemeral",
        "--dangerously-bypass-approvals-and-sandbox",
        "--dangerously-bypass-hook-trust",
        "--skip-git-repo-check",
        // Drawing is an interactive loop. The owner's config may default to max
        // reasoning, which turns every Process tap into a multi-minute wait for
        // what is fundamentally a transcription job.
        "-c",
        "model_reasoning_effort=\"medium\"",
        "--cd",
        PROJECT_DIR,
        "--model",
        model,
        "--output-schema",
        SCHEMA_PATH,
        "--output-last-message",
        outputPath,
        "--color",
        "never",
        "--image",
        imagePath,
        "-",
      ],
      { cwd: PROJECT_DIR, input: prompt },
    );
    const responseText = await readFile(outputPath, "utf8").catch(
      () => result.stdout,
    );
    return parseAgentJson(responseText);
  }

  if (engine === "claude") {
    const result = await runProcess(
      executable,
      [
        "--print",
        "--safe-mode",
        "--no-session-persistence",
        "--dangerously-skip-permissions",
        "--tools",
        "default",
        "--model",
        model,
        "--json-schema",
        JSON.stringify(schema),
        "--output-format",
        "json",
      ],
      { cwd: workDir, input: prompt },
    );
    return parseAgentJson(result.stdout);
  }

  const result = await runProcess(
    executable,
    [
      "--prompt",
      prompt,
      "--silent",
      "--no-custom-instructions",
      "--no-ask-user",
      "--yolo",
      "--experimental",
      "--model",
      model,
      "--attachment",
      imagePath,
      "-C",
      workDir,
    ],
    { cwd: workDir, input: "" },
  );
  return parseAgentJson(result.stdout);
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url || "/", `http://${HOST}:${PORT}`);

  if (request.method === "GET" && url.pathname === "/api/status") {
    const availability = await engineAvailability();
    sendJson(response, 200, {
      available: availability.available,
      models: defaultModels,
      busy,
    });
    return;
  }

  if (request.method !== "POST" || url.pathname !== "/api/process") {
    sendJson(response, 404, { error: "Not found" });
    return;
  }

  if (busy) {
    sendJson(response, 429, {
      error: "Another sketch batch is already being processed.",
    });
    return;
  }

  busy = true;
  let workDir;
  try {
    const input = await readJson(request);
    const engine = ["codex", "claude", "copilot"].includes(input.engine)
      ? input.engine
      : "codex";
    const availability = await engineAvailability();
    const executable = availability.paths[engine];
    if (!executable) {
      sendJson(response, 503, {
        error: `${engine} is not installed or is not on PATH.`,
      });
      return;
    }

    workDir = await mkdtemp(join(tmpdir(), "magicapp-agent-"));
    const imagePath = join(workDir, "sketch.png");
    await writeFile(imagePath, parseImage(input.image));
    const prompt = makePrompt(input, imagePath);
    const model =
      typeof input.model === "string" && input.model.trim()
        ? input.model.trim()
        : defaultModels[engine];
    const result = await invokeAgent(
      engine,
      executable,
      model,
      prompt,
      imagePath,
      workDir,
    );
    sendJson(response, 200, { ...result, engine });
  } catch (error) {
    sendJson(response, 500, {
      error: error instanceof Error ? error.message : "Processing failed.",
    });
  } finally {
    busy = false;
    if (workDir) {
      await rm(workDir, { recursive: true, force: true }).catch(() => {});
    }
  }
});

server.listen(PORT, HOST, () => {
  console.log(`  Agent bridge: http://${HOST}:${PORT}`);
});

function shutdown() {
  server.close(() => process.exit(0));
  setTimeout(() => process.exit(0), 1_000).unref();
}

process.on("SIGINT", shutdown);
process.on("SIGTERM", shutdown);

