// harnesses run on the owner's own Mac. We therefore trust the environment and
// invoke every engine fully unlocked — all tools, no approval prompts, no
// sandbox — rather than negotiating permissions the iPad can't answer.
async function invokeAgent(engine, executable, model, prompt, imagePath, workDir) {
  const outputPath = join(workDir, "response.json");

  if (engine === "codex") {
    const result = await runProcess(
      executable,
      [
        "exec",
        "--ephemeral",
        "--dangerously-bypass-approvals-and-sandbox",
        "--dangerously-bypass-hook-trust",
        "--skip-git-repo-check",
        // Drawing is an interactive loop. The owner's config may default to max
        // reasoning, which turns every Process tap into a multi-minute wait for
        // what is fundamentally a transcription job.
        "-c",
        "model_reasoning_effort=\"medium\"",
        "--cd",
        PROJECT_DIR,
        "--model",
        model,
        "--output-schema",
        SCHEMA_PATH,
        "--output-last-message",
        outputPath,
        "--color",
        "never",
        "--image",
        imagePath,
        "-",
      ],
      { cwd: PROJECT_DIR, input: prompt },
    );
