      () => result.stdout,
    );
    return parseAgentJson(responseText);
  }

  if (engine === "claude") {
    const result = await runProcess(
      executable,
      [
        "--print",
        "--safe-mode",
        "--no-session-persistence",
        "--dangerously-skip-permissions",
        "--tools",
        "default",
        "--model",
        model,
        "--json-schema",
        JSON.stringify(schema),
        "--output-format",
        "json",
      ],
      { cwd: workDir, input: prompt },
    );
    return parseAgentJson(result.stdout);
  }

  const result = await runProcess(
    executable,
    [
      "--prompt",
      prompt,
      "--silent",
      "--no-custom-instructions",
      "--no-ask-user",
      "--yolo",
      "--experimental",
      "--model",
      model,
      "--attachment",
      imagePath,
      "-C",
      workDir,
    ],
    { cwd: workDir, input: "" },
  );
  return parseAgentJson(result.stdout);
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url || "/", `http://${HOST}:${PORT}`);

  if (request.method === "GET" && url.pathname === "/api/status") {
    const availability = await engineAvailability();
    sendJson(response, 200, {
      available: availability.available,
      models: defaultModels,
      busy,
    });
    return;
  }

  if (request.method !== "POST" || url.pathname !== "/api/process") {
    sendJson(response, 404, { error: "Not found" });
    return;
  }

  if (busy) {
    sendJson(response, 429, {
      error: "Another sketch batch is already being processed.",
    });
    return;
  }

  busy = true;
  let workDir;
  try {
    const input = await readJson(request);
    const engine = ["codex", "claude", "copilot"].includes(input.engine)
      ? input.engine
      : "codex";
    const availability = await engineAvailability();
    const executable = availability.paths[engine];
    if (!executable) {
      sendJson(response, 503, {
        error: `${engine} is not installed or is not on PATH.`,
      });
      return;
    }

    workDir = await mkdtemp(join(tmpdir(), "magicapp-agent-"));
    const imagePath = join(workDir, "sketch.png");
    await writeFile(imagePath, parseImage(input.image));
    const prompt = makePrompt(input, imagePath);
    const model =
      typeof input.model === "string" && input.model.trim()
        ? input.model.trim()
        : defaultModels[engine];
    const result = await invokeAgent(
      engine,
      executable,
      model,
      prompt,
      imagePath,
      workDir,
    );
    sendJson(response, 200, { ...result, engine });
  } catch (error) {
    sendJson(response, 500, {
      error: error instanceof Error ? error.message : "Processing failed.",
    });
  } finally {
    busy = false;
    if (workDir) {
      await rm(workDir, { recursive: true, force: true }).catch(() => {});
    }
  }
});

server.listen(PORT, HOST, () => {
  console.log(`  Agent bridge: http://${HOST}:${PORT}`);
});

function shutdown() {
  server.close(() => process.exit(0));
  setTimeout(() => process.exit(0), 1_000).unref();
}

process.on("SIGINT", shutdown);
process.on("SIGTERM", shutdown);

