export const COMPONENT_TYPES = [
  "Text",
  "Button",
  "TextInput",
  "Textarea",
  "Checkbox",
  "Select",
  "Image",
  "Card",
  "List",
  "Modal",
  "Tabs",
  "Navbar",
] as const;

export type ComponentType = (typeof COMPONENT_TYPES)[number];
/** One canvas, two modes: you are either drawing the app or using it. */
export type WorkspaceMode = "draw" | "run";

export interface Point {
  x: number;
  y: number;
  pressure: number;
}

export interface InkStroke {
  id: string;
  points: Point[];
  processed: boolean;
}

export interface Bounds {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface AppComponent {
  id: string;
  type: ComponentType;
  bounds: Bounds;
  props: {
    label: string;
    placeholder: string;
    options: string[];
  };
  dataSource: string;
  /** App-state key this component displays or writes. Empty means unbound. */
  stateKey: string;
  confidence: number;
}

export type ActionType =
  | "setState"
  | "filter"
  | "sort"
  | "validate"
  | "open"
  | "close"
  | "navigate"
  | "fetch"
  | "create"
  | "update"
  | "delete"
  | "visibility"
  | "custom";

export interface BehaviorEdge {
  id: string;
  source: string;
  target: string;
  instruction: string;
  triggerEvent: string;
  actionType: ActionType;
  sourceData: string;
  predicate: string;
  handler: string;
  tests: string[];
  compiledBy: "local" | "codex" | "claude" | "copilot";
}

export interface AppGraph {
  version: 1;
  screens: Array<{ id: string; name: string }>;
  components: AppComponent[];
  /** Starting values for the app-state keys the handlers read and write. */
  initialState: Record<string, string | number | boolean | null>;
  entities: Array<{ id: string; name: string; fields: string[] }>;
  events: Array<{ id: string; component: string; event: string }>;
  actions: Array<{ id: string; type: ActionType; target: string }>;
  bindings: BehaviorEdge[];
  navigation: Array<{ from: string; to: string; condition: string }>;
  constraints: string[];
  agentInstructions: string[];
}

export interface AgentComponent {
  id: string;
  type: string;
  x: number;
  y: number;
  width: number;
  height: number;
  label: string;
  placeholder: string;
  dataSource: string;
  stateKey: string;
  confidence: number;
}

export interface AgentEdge {
  id: string;
  source: string;
  target: string;
  instruction: string;
  triggerEvent: string;
  actionType: string;
  sourceData: string;
  predicate: string;
  handler: string;
  tests: string[];
}

export interface ProcessResponse {
  summary: string;
  components: AgentComponent[];
  edges: AgentEdge[];
  initialState: Record<string, string | number | boolean | null>;
  generatedCode: string;
  tests: string[];
  engine: "codex" | "claude" | "copilot" | "local";
}

export const EMPTY_GRAPH: AppGraph = {
  version: 1,
  screens: [{ id: "screen-1", name: "Untitled screen" }],
  components: [],
  initialState: {},
  entities: [
    {
      id: "tasks",
      name: "Task",
      fields: ["id", "title", "complete", "priority"],
    },
  ],
  events: [],
  actions: [],
  bindings: [],
  navigation: [],
  constraints: [],
  agentInstructions: [],
};

export function createId(prefix: string): string {
  const cryptoApi = globalThis.crypto;

  if (typeof cryptoApi?.randomUUID === "function") {
    return `${prefix}-${cryptoApi.randomUUID().slice(0, 8)}`;
  }

  if (typeof cryptoApi?.getRandomValues === "function") {
    const values = new Uint32Array(2);
    cryptoApi.getRandomValues(values);
    return `${prefix}-${Array.from(values, (value) =>
      value.toString(36),
    ).join("")}`;
  }

  return `${prefix}-${Date.now().toString(36)}${Math.random()
    .toString(36)
    .slice(2, 8)}`;
}

export function getStrokeBounds(stroke: InkStroke): Bounds {
  const xs = stroke.points.map((point) => point.x);
  const ys = stroke.points.map((point) => point.y);
  const x = Math.min(...xs);
  const y = Math.min(...ys);
  return {
    x,
    y,
    width: Math.max(1, Math.max(...xs) - x),
    height: Math.max(1, Math.max(...ys) - y),
  };
}

export function guessComponentType(bounds: Bounds): ComponentType {
  const ratio = bounds.width / Math.max(bounds.height, 1);

  if (bounds.width < 64 && bounds.height < 64) return "Checkbox";
  if (ratio > 4.2) return "TextInput";
  if (ratio > 2.1 && bounds.height < 96) return "Button";
  if (bounds.height > 150 && bounds.height > bounds.width * 0.72) return "List";
  if (bounds.width > 230 && bounds.height > 130) return "Card";
  return "Button";
}

export function defaultProps(type: ComponentType): AppComponent["props"] {
  const defaults: Record<ComponentType, AppComponent["props"]> = {
    Text: { label: "Text", placeholder: "", options: [] },
    Button: { label: "Button", placeholder: "", options: [] },
    TextInput: {
      label: "",
      placeholder: "Type here…",
      options: [],
    },
    Textarea: {
      label: "",
      placeholder: "Write something…",
      options: [],
    },
    Checkbox: { label: "Option", placeholder: "", options: [] },
    Select: {
      label: "Choose…",
      placeholder: "",
      options: ["First", "Second", "Third"],
    },
    Image: { label: "Image", placeholder: "", options: [] },
    Card: { label: "", placeholder: "", options: [] },
    List: { label: "", placeholder: "", options: [] },
    Modal: { label: "Dialog", placeholder: "", options: [] },
    Tabs: {
      label: "",
      placeholder: "",
      options: ["Overview", "Details"],
    },
    Navbar: { label: "App", placeholder: "", options: [] },
  };

  return defaults[type];
}

export function isClosedShape(stroke: InkStroke): boolean {
  if (stroke.points.length < 8) return false;
  const bounds = getStrokeBounds(stroke);
  if (bounds.width < 28 || bounds.height < 22) return false;

  const first = stroke.points[0];
  const last = stroke.points[stroke.points.length - 1];
  const closingDistance = Math.hypot(last.x - first.x, last.y - first.y);
  return closingDistance < Math.max(34, Math.min(bounds.width, bounds.height) * 0.45);
}

export function hitTest(
  point: Point,
  component: AppComponent,
  padding = 0,
): boolean {
  const { x, y, width, height } = component.bounds;
  return (
    point.x >= x - padding &&
    point.x <= x + width + padding &&
    point.y >= y - padding &&
    point.y <= y + height + padding
  );
}

export function sanitizeComponentType(value: string): ComponentType {
  return COMPONENT_TYPES.includes(value as ComponentType)
    ? (value as ComponentType)
    : "Card";
}

export function sanitizeActionType(value: string): ActionType {
  const actions: ActionType[] = [
    "setState",
    "filter",
    "sort",
    "validate",
    "open",
    "close",
    "navigate",
    "fetch",
    "create",
    "update",
    "delete",
    "visibility",
    "custom",
  ];
  return actions.includes(value as ActionType)
    ? (value as ActionType)
    : "custom";
}

export function componentLabel(component: AppComponent): string {
  return (
    component.props.label ||
    component.props.placeholder ||
    component.type.replace(/([a-z])([A-Z])/g, "$1 $2")
  );
}

export function localHandler(
  source: AppComponent,
  target: AppComponent,
): Pick<
  BehaviorEdge,
  "instruction" | "triggerEvent" | "actionType" | "sourceData" | "predicate" | "handler" | "tests"
> {
  const targetKey = target.stateKey || target.id;

  if (
    (source.type === "TextInput" || source.type === "Textarea") &&
    target.type === "List"
  ) {
    return {
      instruction: "filter the list as I type",
      triggerEvent: "change",
      actionType: "filter",
      sourceData: target.dataSource || "tasks",
      predicate: "title contains the input value",
      handler: `set(${JSON.stringify(targetKey)}, String(event.value ?? ""));`,
      tests: [
        "filters records case-insensitively",
        "shows every record for an empty query",
      ],
    };
  }

  if (source.type === "Button" && target.type === "Modal") {
    return {
      instruction: "open the dialog",
      triggerEvent: "click",
      actionType: "open",
      sourceData: "",
      predicate: "",
      handler: `set(${JSON.stringify(openKey(target.id))}, true);`,
      tests: ["opens the target dialog on click"],
    };
  }

  return {
    instruction: `when ${componentLabel(source)} changes, update ${componentLabel(target)}`,
    triggerEvent:
      source.type === "TextInput" ||
      source.type === "Textarea" ||
      source.type === "Checkbox"
        ? "change"
        : "click",
    actionType: "setState",
    sourceData: "",
    predicate: "",
    handler: `set(${JSON.stringify(targetKey)}, event.value);`,
    tests: ["updates the target when the source event fires"],
  };
}

/** State key controlling whether an overlay component is visible. */
export function openKey(componentId: string): string {
  return `open:${componentId}`;
}

