    let id = String(component.id ?? "").replace(/[^a-zA-Z0-9_-]/g, "");
    if (!id) id = createId(type.toLowerCase());
    while (ids.has(id)) id = createId(type.toLowerCase());
    ids.add(id);

    const bounds = (
      component.bounds && typeof component.bounds === "object"
        ? component.bounds
        : {}
    ) as Record<string, unknown>;
    const props = (
      component.props && typeof component.props === "object"
        ? component.props
        : {}
    ) as Record<string, unknown>;

    components.push({
      id,
      type,
      bounds: {
        x: num(bounds.x, 0),
        y: num(bounds.y, 0),
        width: Math.max(1, num(bounds.width, 120)),
        height: Math.max(1, num(bounds.height, 48)),
      },
      props: {
        label: typeof props.label === "string" ? props.label : defaults.label,
        placeholder:
          typeof props.placeholder === "string"
            ? props.placeholder
            : defaults.placeholder,
        options: Array.isArray(props.options)
          ? props.options.map((option) => String(option))
          : defaults.options,
      },
      dataSource:
        typeof component.dataSource === "string" ? component.dataSource : "",
      stateKey: typeof component.stateKey === "string" ? component.stateKey : "",
      confidence: num(component.confidence, 1),
    });
  }

  const bindings: BehaviorEdge[] = [];
  for (const entry of Array.isArray(raw.bindings) ? raw.bindings : []) {
    if (!entry || typeof entry !== "object") continue;
    const edge = entry as Record<string, unknown>;
    const source = String(edge.source ?? "");
    const target = String(edge.target ?? "");
    if (!ids.has(source) || (target && !ids.has(target))) continue;
    const compiledBy = edge.compiledBy;
    bindings.push({
      id: String(edge.id ?? createId("edge")),
      source,
      target,
      instruction: typeof edge.instruction === "string" ? edge.instruction : "",
      triggerEvent:
        typeof edge.triggerEvent === "string" ? edge.triggerEvent : "click",
      actionType: sanitizeActionType(String(edge.actionType ?? "")),
      sourceData: typeof edge.sourceData === "string" ? edge.sourceData : "",
      predicate: typeof edge.predicate === "string" ? edge.predicate : "",
      handler: typeof edge.handler === "string" ? edge.handler : "",
      tests: asStringArray(edge.tests),
      compiledBy: (COMPILED_BY as readonly string[]).includes(
        String(compiledBy),
      )
        ? (compiledBy as BehaviorEdge["compiledBy"])
        : "local",
    });
  }

  const initialState: AppGraph["initialState"] = {};
  if (
    raw.initialState &&
    typeof raw.initialState === "object" &&
    !Array.isArray(raw.initialState)
  ) {
    for (const [key, entry] of Object.entries(
      raw.initialState as Record<string, unknown>,
    )) {
      if (
        typeof entry === "string" ||
        typeof entry === "number" ||
        typeof entry === "boolean" ||
        entry === null
      ) {
        initialState[key] = entry;
      }
    }
  }

  const screens = (Array.isArray(raw.screens) ? raw.screens : []).flatMap(
    (entry) => {
      if (!entry || typeof entry !== "object") return [];
      const screen = entry as Record<string, unknown>;
      return [
        {
          id: String(screen.id ?? createId("screen")),
          name: typeof screen.name === "string" ? screen.name : "Screen",
        },
      ];
    },
  );

  const entities = (Array.isArray(raw.entities) ? raw.entities : []).flatMap(
    (entry) => {
      if (!entry || typeof entry !== "object") return [];
      const entity = entry as Record<string, unknown>;
      return [
        {
          id: String(entity.id ?? createId("entity")),
          name: typeof entity.name === "string" ? entity.name : "Entity",
          fields: asStringArray(entity.fields),
        },
      ];
    },
  );

  const navigation = (
    Array.isArray(raw.navigation) ? raw.navigation : []
  ).flatMap((entry) => {
    if (!entry || typeof entry !== "object") return [];
    const link = entry as Record<string, unknown>;
    return [
      {
        from: String(link.from ?? ""),
        to: String(link.to ?? ""),
        condition: typeof link.condition === "string" ? link.condition : "",
      },
    ];
  });

  return {
    version: 1,
    screens: screens.length > 0 ? screens : EMPTY_GRAPH.screens.map((screen) => ({ ...screen })),
    components,
    initialState,
    entities: entities.length > 0 ? entities : EMPTY_GRAPH.entities.map((entity) => ({ ...entity, fields: [...entity.fields] })),
    events: bindings.map((edge) => ({
      id: `event-${edge.id}`,
      component: edge.source,
      event: edge.triggerEvent,
    })),
    actions: bindings.map((edge) => ({
      id: `action-${edge.id}`,
      type: edge.actionType,
      target: edge.target,
    })),
    bindings,
    navigation,
    constraints: asStringArray(raw.constraints),
    agentInstructions: asStringArray(raw.agentInstructions),
  };
}

