  const updateSelected = (patch: ComponentPatch) => {
    if (!selectedId) return;
    setGraph((current) => ({
      ...current,
      components: current.components.map((component) =>
        component.id === selectedId
          ? {
              ...component,
              ...patch,
              props: { ...component.props, ...patch.props },
            }
          : component,
      ),
    }));
  };

  const deleteSelected = () => {
    if (!selectedId) return;
    saveHistory();
    setGraph((current) => {
      const bindings = current.bindings.filter(
        (edge) => edge.source !== selectedId && edge.target !== selectedId,
      );
      return {
        ...current,
        components: current.components.filter(
          (component) => component.id !== selectedId,
        ),
        bindings,
        events: current.events.filter((event) => event.component !== selectedId),
        actions: current.actions.filter(
          (action) => action.target !== selectedId,
        ),
      };
    });
    setSelectedId(null);
    setSidePanel(null);
  };

  const clearCanvas = () => {
    if (
      !window.confirm(
        "Clear the sketch, components, and behavior graph? Undo can restore it until you reload.",
      )
    ) {
      return;
    }
    saveHistory();
    setGraph(clone(EMPTY_GRAPH));
    setStrokes([]);
    setAppState({});
    setSelectedId(null);
    setSidePanel(null);
    setGeneratedCode("");
    setGeneratedTests([]);
  };

  const selectedComponent = graph.components.find(
    (component) => component.id === selectedId,
  );

  // Processed ink disappears: the component it became is now the drawing.

